import React, { useEffect, useState, useMemo } from 'react';
import api from '../services/api';

const tabs = [
  ['overview',    "📊 Vue d'ensemble"],
  ['profs',       '👨‍🏫 Professeurs'],
  ['demandes',    '💡 Demandes Matières'],
  ['referentiel', '📚 Référentiel'],
];

/* ── Helpers globaux ── */
function isTarifValide(v) {
  return v !== null && v !== undefined && v !== '' && parseFloat(v) > 0;
}

function StatutBadge({ statut }) {
  const cfg = {
    validé:     { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', label: '✅ Validé'     },
    en_attente: { bg: 'rgba(245,158,11,0.12)',  color: '#f59e0b', label: '⏳ En attente' },
    refusé:     { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', label: '❌ Refusé'     },
    approuvé:   { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', label: '✅ Approuvée'  },
  }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', label: statut };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: '.72rem', fontWeight: 700, padding: '4px 10px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      {cfg.label}
    </span>
  );
}

function ModeBadge({ mode }) {
  const map = {
    en_ligne:   { icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.12)'  },
    presentiel: { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)'  },
    les_deux:   { icon: '🔀', label: 'Les deux',   color: '#6c63ff', bg: 'rgba(108,99,255,0.12)' },
  }[mode] || { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)' };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.72rem', fontWeight: 700, padding: '3px 9px', borderRadius: 20, background: map.bg, color: map.color }}>
      {map.icon} {map.label}
    </span>
  );
}

function DrawerSection({ title, children }) {
  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{ fontSize: '.7rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', marginBottom: 10, paddingBottom: 8, borderBottom: '1px solid var(--border)' }}>
        {title}
      </div>
      {children}
    </div>
  );
}

function InfoRow({ icon, label, value, link }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 0', borderBottom: '1px solid var(--border)' }}>
      <span style={{ fontSize: '.9rem', width: 22, textAlign: 'center' }}>{icon}</span>
      <span style={{ fontSize: '.78rem', color: 'var(--text2)', width: 80 }}>{label}</span>
      {link
        ? <a href={link} style={{ fontSize: '.85rem', fontWeight: 600, color: '#6c63ff', textDecoration: 'none' }}>{value}</a>
        : <span style={{ fontSize: '.85rem', fontWeight: 600 }}>{value}</span>}
    </div>
  );
}

function EmptyDrawer({ icon, text, sub }) {
  return (
    <div style={{ textAlign: 'center', padding: '40px 20px', color: 'var(--text2)' }}>
      <div style={{ fontSize: '2.5rem', marginBottom: 10 }}>{icon}</div>
      <div style={{ fontWeight: 600, marginBottom: 4 }}>{text}</div>
      {sub && <div style={{ fontSize: '.8rem' }}>{sub}</div>}
    </div>
  );
}

/* ════════════════════════════════════════════════
   DRAWER DÉTAIL PROFESSEUR
════════════════════════════════════════════════ */
function ProfDrawer({ prof, onClose, onValider, onRefuser }) {
  const [activeTab, setActiveTab] = useState('profil');
  if (!prof) return null;

  const nom           = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const matieres      = prof.tarifs_matieres ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))] : [];
  const tarifsValides = prof.tarifs_matieres ? prof.tarifs_matieres.filter(t => parseFloat(t.tarif) > 0) : [];

  const drawerTabs = [
    { key: 'profil',       label: '👤 Profil'        },
    { key: 'enseignement', label: '📚 Enseignements'  },
    { key: 'documents',    label: '📜 Documents'      },
    { key: 'dispos',       label: '🗓 Disponibilités' },
  ];

  return (
    <>
      <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.65)', backdropFilter: 'blur(5px)', zIndex: 900 }} />
      <div style={{ position: 'fixed', top: 0, right: 0, bottom: 0, width: 520, background: 'var(--surface)', borderLeft: '1px solid var(--border)', zIndex: 901, overflowY: 'auto', animation: 'slideIn .3s cubic-bezier(.34,1.56,.64,1)', boxShadow: '-32px 0 80px rgba(0,0,0,0.5)' }}>
        <style>{`@keyframes slideIn{from{transform:translateX(100%)}to{transform:translateX(0)}}`}</style>

        <div style={{ height: 140, background: 'linear-gradient(135deg,rgba(108,99,255,.5),rgba(255,101,132,.3))', position: 'relative' }}>
          <button onClick={onClose} style={{ position: 'absolute', top: 16, right: 16, width: 36, height: 36, borderRadius: 10, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.15)', cursor: 'pointer', color: '#fff', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
          <div style={{ position: 'absolute', top: 16, left: 16 }}><StatutBadge statut={prof.statut_validation} /></div>
          <div style={{ width: 84, height: 84, borderRadius: '50%', border: '4px solid var(--surface)', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem', overflow: 'hidden', position: 'absolute', bottom: -42, left: 28, boxShadow: '0 8px 24px rgba(0,0,0,0.4)' }}>
            {prof.photo_url ? <img src={'http://localhost:8001' + prof.photo_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
          </div>
        </div>

        <div style={{ padding: '54px 28px 20px', borderBottom: '1px solid var(--border)' }}>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.4rem', margin: '0 0 6px' }}>{nom}</h2>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', marginBottom: 14 }}>
            {prof.ville && <span style={{ fontSize: '.82rem', color: 'var(--text2)' }}>📍 {prof.ville}</span>}
            <ModeBadge mode={prof.mode_enseignement} />
            <div style={{ fontSize: '.82rem' }}>
              <span style={{ color: '#f59e0b' }}>★</span>
              <span style={{ fontWeight: 700, marginLeft: 3 }}>{parseFloat(prof.note_moyenne || 0).toFixed(1)}</span>
              <span style={{ color: 'var(--text2)', marginLeft: 4 }}>({prof.nb_avis} avis)</span>
            </div>
          </div>
          {prof.statut_validation === 'en_attente' && (
            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={() => { onValider(prof.id); onClose(); }} style={{ flex: 1, padding: '11px', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', color: '#000', border: 'none', borderRadius: 10, fontWeight: 700, cursor: 'pointer', fontSize: '.88rem' }}>✅ Valider ce professeur</button>
              <button onClick={() => { onRefuser(prof.id); onClose(); }} style={{ flex: 1, padding: '11px', background: 'rgba(255,101,132,0.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,0.3)', borderRadius: 10, fontWeight: 700, cursor: 'pointer', fontSize: '.88rem' }}>❌ Refuser</button>
            </div>
          )}
          {prof.statut_validation === 'validé' && (
            <div style={{ padding: '8px 14px', background: 'rgba(67,233,123,0.07)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 10, fontSize: '.8rem', color: '#43e97b' }}>
              ✅ Professeur validé et visible sur la plateforme
            </div>
          )}
        </div>

        <div style={{ display: 'flex', borderBottom: '1px solid var(--border)', padding: '0 16px' }}>
          {drawerTabs.map(t => (
            <button key={t.key} onClick={() => setActiveTab(t.key)} style={{ flex: 1, padding: '12px 4px', background: 'none', border: 'none', cursor: 'pointer', fontSize: '.75rem', fontWeight: 600, color: activeTab === t.key ? '#6c63ff' : 'var(--text2)', borderBottom: activeTab === t.key ? '2px solid #6c63ff' : '2px solid transparent', transition: 'all .2s' }}>
              {t.label}
            </button>
          ))}
        </div>

        <div style={{ padding: 24 }}>
          {activeTab === 'profil' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <DrawerSection title="📇 Coordonnées">
                <InfoRow icon="✉️" label="Email"     value={prof.email || '—'}     link={prof.email ? `mailto:${prof.email}` : null} />
                <InfoRow icon="📞" label="Téléphone" value={prof.telephone || '—'} link={prof.telephone ? `tel:${prof.telephone}` : null} />
                <InfoRow icon="📍" label="Ville"     value={prof.ville || '—'} />
              </DrawerSection>
              {prof.bio && (
                <DrawerSection title="📝 Bio">
                  <p style={{ fontSize: '.85rem', color: 'var(--text2)', lineHeight: 1.7, margin: 0, padding: '12px 14px', background: 'var(--surface2)', borderRadius: 10, borderLeft: '3px solid #6c63ff' }}>{prof.bio}</p>
                </DrawerSection>
              )}
              {(isTarifValide(prof.tarif_en_ligne) || isTarifValide(prof.tarif_presentiel)) && (
                <DrawerSection title="💰 Tarifs horaires">
                  <div style={{ display: 'flex', gap: 10 }}>
                    {isTarifValide(prof.tarif_en_ligne) && (
                      <div style={{ flex: 1, padding: '12px', background: 'rgba(56,189,248,0.08)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 10, textAlign: 'center' }}>
                        <div style={{ fontSize: '.72rem', color: '#38bdf8', marginBottom: 4 }}>🌐 En ligne</div>
                        <div style={{ fontFamily: 'Syne', fontWeight: 800, color: '#38bdf8', fontSize: '1.2rem' }}>{prof.tarif_en_ligne} DT</div>
                        <div style={{ fontSize: '.68rem', color: 'var(--text2)' }}>/ heure</div>
                      </div>
                    )}
                    {isTarifValide(prof.tarif_presentiel) && (
                      <div style={{ flex: 1, padding: '12px', background: 'rgba(67,233,123,0.08)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 10, textAlign: 'center' }}>
                        <div style={{ fontSize: '.72rem', color: '#43e97b', marginBottom: 4 }}>🏫 Présentiel</div>
                        <div style={{ fontFamily: 'Syne', fontWeight: 800, color: '#43e97b', fontSize: '1.2rem' }}>{prof.tarif_presentiel} DT</div>
                        <div style={{ fontSize: '.68rem', color: 'var(--text2)' }}>/ heure</div>
                      </div>
                    )}
                  </div>
                </DrawerSection>
              )}
            </div>
          )}

          {activeTab === 'enseignement' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              {matieres.length > 0 ? (
                <DrawerSection title="📚 Matières enseignées">
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                    {matieres.map(m => <span key={m} style={{ fontSize: '.78rem', fontWeight: 600, padding: '5px 13px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.2)' }}>{m}</span>)}
                  </div>
                </DrawerSection>
              ) : <EmptyDrawer icon="📚" text="Aucune matière renseignée" />}
              {prof.niveaux && prof.niveaux.length > 0 && (
                <DrawerSection title="🎓 Niveaux">
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                    {prof.niveaux.map(n => <span key={n} style={{ fontSize: '.78rem', fontWeight: 600, padding: '5px 13px', borderRadius: 20, background: 'var(--surface2)', color: 'var(--text2)', border: '1px solid var(--border)' }}>{n}</span>)}
                  </div>
                </DrawerSection>
              )}
              {tarifsValides.length > 0 && (
                <DrawerSection title="💰 Tarifs par matière">
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {tarifsValides.map((t, i) => (
                      <div key={i} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 12px', background: 'var(--surface2)', borderRadius: 8, border: '1px solid var(--border)' }}>
                        <div><span style={{ fontWeight: 600, fontSize: '.85rem' }}>{t.nom_matiere}</span><span style={{ fontSize: '.75rem', color: 'var(--text2)', marginLeft: 8 }}>{t.nom_niveau}</span></div>
                        <span style={{ fontWeight: 800, color: '#43e97b', fontSize: '.88rem' }}>{t.tarif} DT/h</span>
                      </div>
                    ))}
                  </div>
                </DrawerSection>
              )}
            </div>
          )}

          {activeTab === 'documents' && (
            prof.certificats && prof.certificats.length > 0 ? (
              <DrawerSection title="📜 Diplômes et Certificats">
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                  {prof.certificats.map(c => (
                    <a key={c.id} href={'http://localhost:8001' + c.fichier_url} target="_blank" rel="noreferrer" style={{ textDecoration: 'none' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '14px 16px', background: 'linear-gradient(135deg,rgba(108,99,255,0.08),rgba(255,101,132,0.05))', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 12, cursor: 'pointer', transition: 'all .2s' }}
                        onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(108,99,255,0.5)'; }}
                        onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(108,99,255,0.2)'; }}>
                        <div style={{ width: 44, height: 44, borderRadius: 10, background: 'rgba(108,99,255,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.3rem', flexShrink: 0 }}>
                          {c.fichier_url && c.fichier_url.endsWith('.pdf') ? '📄' : '🖼️'}
                        </div>
                        <div style={{ flex: 1 }}>
                          <div style={{ fontWeight: 700, fontSize: '.88rem', marginBottom: 2 }}>{c.titre}</div>
                          {c.description && <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>{c.description}</div>}
                          <div style={{ fontSize: '.7rem', color: '#6c63ff', marginTop: 3 }}>Cliquer pour consulter →</div>
                        </div>
                        <div style={{ fontSize: '1.1rem', color: '#6c63ff' }}>↗</div>
                      </div>
                    </a>
                  ))}
                </div>
              </DrawerSection>
            ) : <EmptyDrawer icon="📜" text="Aucun document uploadé" sub="Ce professeur n'a pas encore ajouté ses diplômes." />
          )}

          {activeTab === 'dispos' && (
            prof.disponibilites && prof.disponibilites.length > 0 ? (
              <DrawerSection title="🗓 Créneaux planifiés">
                <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {prof.disponibilites.map(d => {
                    const pct  = d.nb_max_etudiants > 0 ? Math.round((d.nb_inscrits / d.nb_max_etudiants) * 100) : 0;
                    const full = pct >= 100;
                    return (
                      <div key={d.id} style={{ padding: '10px 14px', background: 'var(--surface2)', borderRadius: 10, border: `1px solid ${full ? 'rgba(255,101,132,0.3)' : 'var(--border)'}`, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <div style={{ fontWeight: 600, fontSize: '.85rem', marginBottom: 2 }}>📆 {d.date_specifique}</div>
                          <div style={{ fontSize: '.78rem', color: 'var(--accent)' }}>🕒 {d.heure_debut} – {d.heure_fin}</div>
                        </div>
                        <div style={{ fontSize: '.73rem', color: full ? '#ff6584' : '#43e97b', fontWeight: 700 }}>
                          {full ? '🔴 Complet' : `👥 ${d.nb_inscrits}/${d.nb_max_etudiants}`}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </DrawerSection>
            ) : <EmptyDrawer icon="🗓" text="Aucun créneau planifié" />
          )}
        </div>
      </div>
    </>
  );
}

/* ════════════════════════════════════════════════
   CARTE PROFESSEUR
════════════════════════════════════════════════ */
function ProfCard({ prof, onView, onValider, onRefuser }) {
  const [hovered, setHovered] = useState(false);
  const nom      = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const matieres = prof.tarifs_matieres ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 3) : [];
  const showTarifLigne      = isTarifValide(prof.tarif_en_ligne);
  const showTarifPresentiel = isTarifValide(prof.tarif_presentiel);

  return (
    <div onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}
      style={{ background: 'var(--card)', border: hovered ? '1px solid rgba(108,99,255,0.5)' : '1px solid var(--border)', borderRadius: 20, overflow: 'hidden', cursor: 'pointer', transform: hovered ? 'translateY(-3px)' : 'none', boxShadow: hovered ? '0 12px 40px rgba(108,99,255,0.18)' : 'none', transition: 'all .25s cubic-bezier(.34,1.56,.64,1)' }}>
      <div style={{ height: 72, background: hovered ? 'linear-gradient(135deg,rgba(108,99,255,.5),rgba(255,101,132,.35))' : 'linear-gradient(135deg,rgba(108,99,255,.3),rgba(255,101,132,.2))', position: 'relative', transition: 'background .3s' }}>
        <div style={{ position: 'absolute', top: 10, right: 12 }}><StatutBadge statut={prof.statut_validation} /></div>
        <div style={{ width: 64, height: 64, borderRadius: '50%', border: '3px solid var(--card)', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.5rem', overflow: 'hidden', position: 'absolute', bottom: -32, left: 18 }}>
          {prof.photo_url ? <img src={'http://localhost:8001' + prof.photo_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
        </div>
      </div>
      <div style={{ padding: '38px 18px 18px' }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem', marginBottom: 2 }}>{nom}</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10, flexWrap: 'wrap' }}>
          {prof.ville && <span style={{ fontSize: '.75rem', color: 'var(--text2)' }}>📍 {prof.ville}</span>}
          <ModeBadge mode={prof.mode_enseignement} />
        </div>
        {(showTarifLigne || showTarifPresentiel) && (
          <div style={{ display: 'flex', gap: 6, marginBottom: 10 }}>
            {showTarifLigne && <div style={{ flex: 1, padding: '5px 8px', background: 'rgba(56,189,248,0.08)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 7, textAlign: 'center' }}><div style={{ fontSize: '.6rem', color: '#38bdf8' }}>🌐</div><div style={{ fontWeight: 800, color: '#38bdf8', fontSize: '.85rem' }}>{prof.tarif_en_ligne} DT/h</div></div>}
            {showTarifPresentiel && <div style={{ flex: 1, padding: '5px 8px', background: 'rgba(67,233,123,0.08)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 7, textAlign: 'center' }}><div style={{ fontSize: '.6rem', color: '#43e97b' }}>🏫</div><div style={{ fontWeight: 800, color: '#43e97b', fontSize: '.85rem' }}>{prof.tarif_presentiel} DT/h</div></div>}
          </div>
        )}
        {matieres.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: 10 }}>
            {matieres.map(m => <span key={m} style={{ fontSize: '.65rem', fontWeight: 600, padding: '2px 7px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff' }}>{m}</span>)}
          </div>
        )}
        <div style={{ display: 'flex', alignItems: 'center', gap: 4, marginBottom: 14, fontSize: '.78rem' }}>
          <span style={{ color: '#f59e0b' }}>★</span>
          <span style={{ fontWeight: 700 }}>{parseFloat(prof.note_moyenne || 0).toFixed(1)}</span>
          <span style={{ color: 'var(--text2)' }}>{prof.nb_avis} avis</span>
        </div>
        <div style={{ display: 'flex', gap: 7 }}>
          <button onClick={() => onView(prof)} style={{ flex: 1, padding: '8px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 9, fontWeight: 600, cursor: 'pointer', fontSize: '.78rem' }}>👁 Voir profil</button>
          {prof.statut_validation === 'en_attente' && (
            <button onClick={e => { e.stopPropagation(); onValider(prof.id); }} style={{ padding: '8px 10px', background: 'rgba(67,233,123,0.15)', color: '#43e97b', border: '1px solid rgba(67,233,123,0.3)', borderRadius: 9, cursor: 'pointer', fontSize: '.78rem', fontWeight: 600 }}>✅</button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   ONGLET RÉFÉRENTIEL
════════════════════════════════════════════════ */
function ReferentielTab({ structure, villes, onReload }) {
  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%', boxSizing: 'border-box' };

  const [search, setSearch]           = useState('');
  const [expandedDom, setExpandedDom] = useState({});
  const [modal, setModal]             = useState(null);
  const [formVal, setFormVal]         = useState('');
  const [saving, setSaving]           = useState(false);
  const [delConf, setDelConf]         = useState(null);

  const totalMatieres = structure.reduce((s, d) => s + (d.niveaux?.reduce((s2, n) => s2 + (n.matieres?.length || 0), 0) || 0), 0);
  const totalNiveaux  = structure.reduce((s, d) => s + (d.niveaux?.length || 0), 0);

  const domColors = [
    { color: '#6c63ff', bg: 'rgba(108,99,255,0.08)', border: 'rgba(108,99,255,0.25)', light: 'rgba(108,99,255,0.1)' },
    { color: '#f59e0b', bg: 'rgba(245,158,11,0.08)',  border: 'rgba(245,158,11,0.25)',  light: 'rgba(245,158,11,0.1)'  },
    { color: '#43e97b', bg: 'rgba(67,233,123,0.08)',  border: 'rgba(67,233,123,0.25)',  light: 'rgba(67,233,123,0.1)'  },
    { color: '#ff6584', bg: 'rgba(255,101,132,0.08)', border: 'rgba(255,101,132,0.25)', light: 'rgba(255,101,132,0.1)' },
    { color: '#38bdf8', bg: 'rgba(56,189,248,0.08)',  border: 'rgba(56,189,248,0.25)',  light: 'rgba(56,189,248,0.1)'  },
  ];

  const filteredStructure = useMemo(() => {
    if (!search) return structure;
    const q = search.toLowerCase();
    return structure.map(dom => ({
      ...dom,
      niveaux: dom.niveaux?.map(niv => ({
        ...niv,
        matieres: niv.matieres?.filter(m => m.nom.toLowerCase().includes(q)) || [],
      })).filter(niv => niv.matieres.length > 0 || niv.nom.toLowerCase().includes(q)),
    })).filter(dom => dom.niveaux?.length > 0 || dom.nom.toLowerCase().includes(q));
  }, [structure, search]);

  const isDomExpanded = (id) => expandedDom[id] !== false;
  const toggleDom     = (id) => setExpandedDom(prev => ({ ...prev, [id]: !isDomExpanded(id) }));
  const openModal     = (type, payload = {}) => { setFormVal(''); setModal({ type, payload }); };

  const handleSave = async () => {
    if (!formVal.trim()) return;
    setSaving(true);
    try {
      const { type, payload } = modal;
      if (type === 'ville')   await api.post('/api/admin/referentiel/villes',   { nom: formVal.trim() });
      if (type === 'domaine') await api.post('/api/admin/referentiel/domaines',  { nom: formVal.trim() });
      if (type === 'niveau')  await api.post('/api/admin/referentiel/niveaux',   { nom: formVal.trim(), domaine_id: payload.domaineId });
      if (type === 'matiere') await api.post('/api/admin/referentiel/matieres',  { nom: formVal.trim(), niveau_id: payload.niveauId });
      setModal(null); setFormVal(''); onReload();
    } catch (e) { alert(e.response?.data?.detail || 'Erreur'); }
    finally { setSaving(false); }
  };

  const handleDelete = async () => {
    if (!delConf) return;
    try {
      if (delConf.type === 'matiere') await api.delete(`/api/admin/referentiel/matieres/${delConf.id}`);
      if (delConf.type === 'ville')   await api.delete(`/api/admin/referentiel/villes/${delConf.id}`);
      if (delConf.type === 'niveau')  await api.delete(`/api/admin/referentiel/niveaux/${delConf.id}`);
      if (delConf.type === 'domaine') await api.delete(`/api/admin/referentiel/domaines/${delConf.id}`);
      setDelConf(null); onReload();
    } catch (e) { alert(e.response?.data?.detail || 'Erreur suppression'); }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 14 }}>
        {[
          { icon: '🏙️', val: villes.length,   lbl: 'Villes',   color: '#38bdf8', bg: 'rgba(56,189,248,.1)'  },
          { icon: '📁', val: structure.length, lbl: 'Domaines', color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
          { icon: '🎓', val: totalNiveaux,      lbl: 'Niveaux',  color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
          { icon: '📚', val: totalMatieres,     lbl: 'Matières', color: '#43e97b', bg: 'rgba(67,233,123,.1)' },
        ].map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '14px 18px', display: 'flex', alignItems: 'center', gap: 12 }}>
            <div style={{ width: 40, height: 40, borderRadius: 11, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0 }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.5rem', color: s.color, lineHeight: 1 }}>{s.val}</div>
              <div style={{ fontSize: '.73rem', color: 'var(--text2)', marginTop: 2 }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Recherche */}
      <div style={{ display: 'flex', gap: 12 }}>
        <div style={{ position: 'relative', flex: 1 }}>
          <span style={{ position: 'absolute', left: 13, top: '50%', transform: 'translateY(-50%)' }}>🔍</span>
          <input style={{ ...inp, paddingLeft: 36 }} placeholder="Rechercher une matière, un niveau, un domaine..." value={search} onChange={e => setSearch(e.target.value)} />
        </div>
        {search && <button onClick={() => setSearch('')} style={{ padding: '9px 14px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, cursor: 'pointer', color: 'var(--text2)', fontSize: '.82rem' }}>✕</button>}
      </div>

      {/* Villes */}
      <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, overflow: 'hidden' }}>
        <div style={{ padding: '18px 22px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: 'linear-gradient(135deg,rgba(56,189,248,0.06),transparent)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <div style={{ width: 36, height: 36, borderRadius: 10, background: 'rgba(56,189,248,0.12)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>🏙️</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem' }}>Villes actives</div>
              <div style={{ fontSize: '.73rem', color: 'var(--text2)' }}>{villes.length} ville{villes.length !== 1 ? 's' : ''}</div>
            </div>
          </div>
          <button onClick={() => openModal('ville')} style={{ display: 'flex', alignItems: 'center', gap: 7, padding: '8px 16px', background: 'linear-gradient(135deg,#38bdf8,#0ea5e9)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 600, cursor: 'pointer', fontSize: '.82rem' }}>
            + Ajouter une ville
          </button>
        </div>
        <div style={{ padding: '18px 22px' }}>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {villes.map(v => (
              <div key={v.id} style={{ display: 'inline-flex', alignItems: 'center', gap: 8, padding: '7px 13px', background: 'rgba(56,189,248,0.07)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 20, fontSize: '.84rem', fontWeight: 600, color: '#38bdf8' }}>
                <span>📍</span>{v.nom}
                <span onClick={() => setDelConf({ type: 'ville', id: v.id, nom: v.nom })} style={{ width: 16, height: 16, borderRadius: '50%', background: 'rgba(255,101,132,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', fontSize: '.6rem', color: '#ff6584', fontWeight: 800 }} title="Supprimer">✕</span>
              </div>
            ))}
            {villes.length === 0 && <div style={{ color: 'var(--text2)', fontSize: '.85rem', fontStyle: 'italic' }}>Aucune ville configurée</div>}
          </div>
        </div>
      </div>

      {/* Titre + bouton nouveau domaine */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.05rem' }}>📚 Structure pédagogique</div>
        <button onClick={() => openModal('domaine')} style={{ display: 'flex', alignItems: 'center', gap: 7, padding: '8px 16px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 600, cursor: 'pointer', fontSize: '.82rem' }}>
          + Nouveau domaine
        </button>
      </div>

      {search && filteredStructure.length === 0 && (
        <div style={{ textAlign: 'center', padding: '40px', background: 'var(--card)', borderRadius: 20, border: '1px solid var(--border)', color: 'var(--text2)' }}>
          <div style={{ fontSize: '2rem', marginBottom: 10 }}>🔍</div>
          <div style={{ fontWeight: 600 }}>Aucun résultat pour "{search}"</div>
        </div>
      )}

      {/* Domaines */}
      {filteredStructure.map((dom, di) => {
        const col      = domColors[di % domColors.length];
        const expanded = isDomExpanded(dom.id);
        const nbMat    = dom.niveaux?.reduce((s, n) => s + (n.matieres?.length || 0), 0) || 0;

        return (
          <div key={dom.id} style={{ background: 'var(--card)', border: `1px solid ${col.border}`, borderRadius: 20, overflow: 'hidden' }}>

            {/* Header domaine */}
            <div style={{ padding: '18px 22px', background: col.bg, borderBottom: expanded ? `1px solid ${col.border}` : 'none', display: 'flex', alignItems: 'center', gap: 14, cursor: 'pointer' }} onClick={() => toggleDom(dom.id)}>
              <div style={{ width: 40, height: 40, borderRadius: 11, background: col.light, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0 }}>📁</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.05rem', color: col.color }}>{dom.nom}</div>
                <div style={{ fontSize: '.73rem', color: 'var(--text2)', marginTop: 2 }}>
                  {dom.niveaux?.length || 0} niveau{(dom.niveaux?.length || 0) !== 1 ? 'x' : ''} · {nbMat} matière{nbMat !== 1 ? 's' : ''}
                </div>
              </div>
              <div style={{ display: 'flex', gap: 8 }} onClick={e => e.stopPropagation()}>
                <button onClick={() => openModal('niveau', { domaineId: dom.id, domaineName: dom.nom })} style={{ padding: '6px 12px', background: col.light, color: col.color, border: `1px solid ${col.border}`, borderRadius: 9, cursor: 'pointer', fontWeight: 600, fontSize: '.78rem' }}>+ Niveau</button>
                <button onClick={() => setDelConf({ type: 'domaine', id: dom.id, nom: dom.nom })} style={{ width: 28, height: 28, borderRadius: 8, background: 'rgba(255,101,132,0.1)', border: '1px solid rgba(255,101,132,0.2)', cursor: 'pointer', color: '#ff6584', fontSize: '.75rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>🗑</button>
              </div>
              <span style={{ color: col.color, fontSize: '.9rem', transition: 'transform .2s', transform: expanded ? 'rotate(0)' : 'rotate(-90deg)', display: 'inline-block' }}>▾</span>
            </div>

            {/* Niveaux */}
            {expanded && (
              <div style={{ padding: '18px 22px', display: 'flex', flexDirection: 'column', gap: 12 }}>
                {dom.niveaux?.length === 0 && (
                  <div style={{ textAlign: 'center', padding: '16px', color: 'var(--text2)', fontSize: '.85rem', fontStyle: 'italic' }}>
                    Aucun niveau —{' '}
                    <span style={{ color: col.color, cursor: 'pointer', fontWeight: 600 }} onClick={() => openModal('niveau', { domaineId: dom.id, domaineName: dom.nom })}>Ajouter un niveau</span>
                  </div>
                )}
                {dom.niveaux?.map(niv => (
                  <div key={niv.id} style={{ background: 'var(--surface2)', borderRadius: 14, border: '1px solid var(--border)', overflow: 'hidden' }}>
                    <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span>🎓</span>
                        <span style={{ fontWeight: 700, fontSize: '.92rem' }}>{niv.nom}</span>
                        <span style={{ fontSize: '.7rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20, background: col.light, color: col.color }}>
                          {niv.matieres?.length || 0} matière{(niv.matieres?.length || 0) !== 1 ? 's' : ''}
                        </span>
                      </div>
                      <div style={{ display: 'flex', gap: 7 }}>
                        <button onClick={() => openModal('matiere', { niveauId: niv.id, niveauName: niv.nom, domaineName: dom.nom })} style={{ display: 'flex', alignItems: 'center', gap: 5, padding: '5px 11px', background: col.light, color: col.color, border: `1px solid ${col.border}`, borderRadius: 8, cursor: 'pointer', fontWeight: 700, fontSize: '.75rem' }}>+ Ajouter matière</button>
                        <button onClick={() => setDelConf({ type: 'niveau', id: niv.id, nom: niv.nom })} style={{ width: 26, height: 26, borderRadius: 7, background: 'rgba(255,101,132,0.1)', border: '1px solid rgba(255,101,132,0.2)', cursor: 'pointer', color: '#ff6584', fontSize: '.7rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>🗑</button>
                      </div>
                    </div>
                    <div style={{ padding: '12px 16px' }}>
                      {niv.matieres?.length === 0 ? (
                        <div style={{ fontSize: '.8rem', color: 'var(--text2)', fontStyle: 'italic' }}>Aucune matière</div>
                      ) : (
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                          {niv.matieres?.map(m => (
                            <div key={m.id}
                              style={{ display: 'inline-flex', alignItems: 'center', gap: 8, padding: '6px 12px', background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, fontSize: '.82rem', fontWeight: 500, transition: 'all .15s' }}
                              onMouseEnter={e => { e.currentTarget.style.borderColor = col.color; e.currentTarget.style.background = col.light; }}
                              onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; e.currentTarget.style.background = 'var(--card)'; }}
                            >
                              <span style={{ width: 6, height: 6, borderRadius: '50%', background: col.color, flexShrink: 0 }} />
                              {m.nom}
                              <span onClick={() => setDelConf({ type: 'matiere', id: m.id, nom: m.nom })} style={{ width: 16, height: 16, borderRadius: '50%', background: 'rgba(255,101,132,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', fontSize: '.58rem', color: '#ff6584', fontWeight: 800, flexShrink: 0 }} title="Supprimer">✕</span>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        );
      })}

      {/* Modal ajout */}
      {modal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', backdropFilter: 'blur(4px)', zIndex: 2000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
          <div style={{ background: 'var(--surface)', borderRadius: 22, border: '1px solid var(--border)', width: '100%', maxWidth: 420, padding: 28, boxShadow: '0 24px 80px rgba(0,0,0,0.5)', animation: 'modalIn .2s ease' }}>
            <style>{`@keyframes modalIn{from{opacity:0;transform:scale(.95)}to{opacity:1;transform:scale(1)}}`}</style>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 18 }}>
              <h3 style={{ fontFamily: 'Syne', margin: 0, fontSize: '1.05rem' }}>
                {modal.type === 'ville'   && '🏙️ Nouvelle ville'}
                {modal.type === 'domaine' && '📁 Nouveau domaine'}
                {modal.type === 'niveau'  && '🎓 Nouveau niveau'}
                {modal.type === 'matiere' && '📚 Nouvelle matière'}
              </h3>
              <button onClick={() => setModal(null)} style={{ width: 28, height: 28, borderRadius: 8, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: 'pointer', color: 'var(--text)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
            </div>
            {(modal.payload?.domaineName || modal.payload?.niveauName) && (
              <div style={{ fontSize: '.8rem', color: 'var(--text2)', marginBottom: 14, padding: '7px 12px', background: 'var(--surface2)', borderRadius: 8 }}>
                {modal.type === 'niveau'  && `📁 Domaine : ${modal.payload.domaineName}`}
                {modal.type === 'matiere' && `🎓 Niveau : ${modal.payload.niveauName} · ${modal.payload.domaineName}`}
              </div>
            )}
            <input
              autoFocus
              style={{ background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 11, color: 'var(--text)', padding: '11px 14px', fontSize: '.9rem', width: '100%', outline: 'none', boxSizing: 'border-box', marginBottom: 16 }}
              placeholder={
                modal.type === 'ville'   ? 'Ex: Zaghouan, Gafsa...' :
                modal.type === 'domaine' ? 'Ex: Arts & Musique, Sport...' :
                modal.type === 'niveau'  ? 'Ex: BTS, Classes préparatoires...' :
                'Ex: Algorithmes, Comptabilité...'
              }
              value={formVal}
              onChange={e => setFormVal(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSave()}
            />
            <div style={{ display: 'flex', gap: 10 }}>
              <button disabled={!formVal.trim() || saving} onClick={handleSave}
                style={{ flex: 2, padding: 12, background: !formVal.trim() || saving ? 'var(--border)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 700, cursor: !formVal.trim() || saving ? 'not-allowed' : 'pointer', fontSize: '.88rem' }}>
                {saving ? '⏳...' : '✅ Enregistrer'}
              </button>
              <button onClick={() => setModal(null)} style={{ flex: 1, padding: 12, background: 'var(--surface2)', color: 'var(--text)', border: '1px solid var(--border)', borderRadius: 10, cursor: 'pointer' }}>Annuler</button>
            </div>
          </div>
        </div>
      )}

      {/* Confirmation suppression */}
      {delConf && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', backdropFilter: 'blur(4px)', zIndex: 2000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
          <div style={{ background: 'var(--surface)', borderRadius: 22, border: '1px solid rgba(255,101,132,0.3)', width: '100%', maxWidth: 380, padding: 28, textAlign: 'center', boxShadow: '0 24px 80px rgba(0,0,0,0.5)' }}>
            <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'rgba(255,101,132,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.5rem', margin: '0 auto 16px' }}>🗑️</div>
            <h3 style={{ fontFamily: 'Syne', margin: '0 0 8px' }}>Confirmer la suppression</h3>
            <p style={{ color: 'var(--text2)', fontSize: '.85rem', margin: '0 0 20px' }}>
              Supprimer <strong style={{ color: 'var(--text)' }}>"{delConf.nom}"</strong> ?<br />
              <span style={{ fontSize: '.78rem', color: '#ff6584' }}>Cette action est irréversible.</span>
            </p>
            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={handleDelete} style={{ flex: 1, padding: 12, background: 'linear-gradient(135deg,#ff6584,#f43f5e)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 700, cursor: 'pointer' }}>🗑 Supprimer</button>
              <button onClick={() => setDelConf(null)} style={{ flex: 1, padding: 12, background: 'var(--surface2)', color: 'var(--text)', border: '1px solid var(--border)', borderRadius: 10, cursor: 'pointer' }}>Annuler</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ════════════════════════════════════════════════
   ADMIN PRINCIPAL
════════════════════════════════════════════════ */
export default function Admin() {
  const [tab, setTab]             = useState('overview');
  const [stats, setStats]         = useState({});
  const [allProfs, setAllProfs]   = useState([]);
  const [structure, setStructure] = useState([]);
  const [villes, setVilles]       = useState([]);
  const [demandes, setDemandes]   = useState([]);
  const [loading, setLoading]     = useState(true);
  const [selectedProf, setSelectedProf] = useState(null);
  const [filterStatut, setFilterStatut] = useState('tous');
  const [searchProf, setSearchProf]     = useState('');

  useEffect(() => { loadAllData(); }, []);

  const loadAllData = async () => {
    setLoading(true);
    try {
      const [s, allP, struct, v, dem] = await Promise.all([
        api.get('/api/admin/stats'),
        api.get('/api/admin/professeurs/all'),
        api.get('/api/admin/referentiel/structure'),
        api.get('/api/admin/referentiel/villes'),
        api.get('/api/admin/demandes-matieres'),
      ]);
      setStats(s.data);
      setAllProfs(allP.data);
      setStructure(struct.data);
      setVilles(v.data);
      setDemandes(dem.data);
    } catch (err) {
      console.error('Erreur chargement admin', err);
    } finally {
      setLoading(false);
    }
  };

  const handleValider = async (id) => { await api.put(`/api/admin/professeurs/${id}/valider`); alert('✅ Professeur validé'); loadAllData(); };
  const handleRefuser = async (id) => { if (!window.confirm('Refuser ?')) return; await api.put(`/api/admin/professeurs/${id}/refuser`); loadAllData(); };
  const handleApprouverDemande = async (id) => {
    try { await api.put(`/api/admin/demandes-matieres/${id}/approuver`); alert('✅ Matière approuvée !'); loadAllData(); }
    catch (e) { alert('Erreur : ' + (e.response?.data?.detail || e.message)); }
  };
  const handleRefuserDemande = async (id) => {
    if (!window.confirm('Refuser cette demande ?')) return;
    try { await api.put(`/api/admin/demandes-matieres/${id}/refuser`); loadAllData(); }
    catch (e) { alert('Erreur : ' + (e.response?.data?.detail || e.message)); }
  };

  const profsFiltered = useMemo(() => allProfs.filter(p => {
    const nom = `${p.user_prenom || ''} ${p.user_nom || ''}`.toLowerCase();
    const matchSearch = !searchProf || nom.includes(searchProf.toLowerCase()) || (p.ville || '').toLowerCase().includes(searchProf.toLowerCase());
    const matchStatut = filterStatut === 'tous' || p.statut_validation === filterStatut;
    return matchSearch && matchStatut;
  }), [allProfs, searchProf, filterStatut]);

  const pendingProfs = allProfs.filter(p => p.statut_validation === 'en_attente');
  const counts = useMemo(() => ({
    tous:       allProfs.length,
    validé:     allProfs.filter(p => p.statut_validation === 'validé').length,
    en_attente: allProfs.filter(p => p.statut_validation === 'en_attente').length,
    refusé:     allProfs.filter(p => p.statut_validation === 'refusé').length,
  }), [allProfs]);

  const demandesPending = demandes.filter(d => d.statut === 'en_attente').length;
  const tabStyle = (t) => ({ flex: 1, padding: '11px', textAlign: 'center', borderRadius: 12, cursor: 'pointer', fontWeight: 600, fontSize: '.88rem', transition: '.2s', background: tab === t ? '#6c63ff' : 'transparent', color: tab === t ? '#fff' : 'var(--text2)', border: 'none', position: 'relative' });
  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '9px 14px', fontSize: '.85rem', outline: 'none' };

  const statCards = [
    { icon: '👥', val: stats.total_users              || 0, lbl: 'Utilisateurs',      color: '#6c63ff', bg: 'rgba(108,99,255,.1)'  },
    { icon: '👨‍🏫', val: counts.validé                  || 0, lbl: 'Profs validés',     color: '#43e97b', bg: 'rgba(67,233,123,.1)'  },
    { icon: '⏳', val: counts.en_attente               || 0, lbl: 'En attente',        color: '#f59e0b', bg: 'rgba(245,158,11,.1)'  },
    { icon: '📅', val: stats.total_reservations        || 0, lbl: 'Réservations',      color: '#38bdf8', bg: 'rgba(56,189,248,.1)'  },
    { icon: '💡', val: stats.demandes_matieres_pending || 0, lbl: 'Demandes matières', color: '#ff6584', bg: 'rgba(255,101,132,.1)' },
  ];

  return (
    <div style={{ padding: 32, maxWidth: 1300, margin: '0 auto' }}>
      <div style={{ fontFamily: 'Syne', fontSize: '1.8rem', fontWeight: 800, marginBottom: 32 }}>🛠 Dashboard Admin</div>

      {/* STATS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5,1fr)', gap: 16, marginBottom: 32 }}>
        {statCards.map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 20 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', marginBottom: 14 }}>{s.icon}</div>
            <div style={{ fontFamily: 'Syne', fontSize: '1.7rem', fontWeight: 800, color: s.color }}>{s.val}</div>
            <div style={{ fontSize: '.8rem', color: 'var(--text2)' }}>{s.lbl}</div>
          </div>
        ))}
      </div>

      {/* ONGLETS */}
      <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 16, padding: 6, marginBottom: 32, gap: 4 }}>
        {tabs.map(([k, l]) => (
          <button key={k} style={tabStyle(k)} onClick={() => setTab(k)}>
            {l}
            {k === 'demandes' && demandesPending > 0 && <span style={{ position: 'absolute', top: 4, right: 8, background: '#ff6584', color: '#fff', fontSize: '.6rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20 }}>{demandesPending}</span>}
            {k === 'profs'    && counts.en_attente > 0 && <span style={{ position: 'absolute', top: 4, right: 8, background: '#f59e0b', color: '#000', fontSize: '.6rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20 }}>{counts.en_attente}</span>}
          </button>
        ))}
      </div>

      {/* VUE D'ENSEMBLE */}
      {tab === 'overview' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
          {(pendingProfs.length > 0 || demandesPending > 0) && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {pendingProfs.length > 0 && (
                <div onClick={() => setTab('profs')} style={{ padding: '14px 20px', background: 'rgba(245,158,11,0.07)', border: '1px solid rgba(245,158,11,0.25)', borderRadius: 14, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 12 }}
                  onMouseEnter={e => e.currentTarget.style.background = 'rgba(245,158,11,0.12)'}
                  onMouseLeave={e => e.currentTarget.style.background = 'rgba(245,158,11,0.07)'}>
                  <span style={{ fontSize: '1.3rem' }}>👨‍🏫</span>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 700, color: '#f59e0b' }}>{pendingProfs.length} professeur{pendingProfs.length > 1 ? 's' : ''} en attente de validation</div>
                    <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 2 }}>Consultez leurs profils avant de valider ou refuser.</div>
                  </div>
                  <span style={{ color: '#f59e0b', fontWeight: 700, fontSize: '.85rem' }}>Examiner →</span>
                </div>
              )}
              {demandesPending > 0 && (
                <div onClick={() => setTab('demandes')} style={{ padding: '14px 20px', background: 'rgba(255,101,132,0.07)', border: '1px solid rgba(255,101,132,0.25)', borderRadius: 14, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 12 }}
                  onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,101,132,0.12)'}
                  onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,101,132,0.07)'}>
                  <span style={{ fontSize: '1.3rem' }}>💡</span>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 700, color: '#ff6584' }}>{demandesPending} demande{demandesPending > 1 ? 's' : ''} de matière en attente</div>
                    <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginTop: 2 }}>Des professeurs souhaitent ajouter de nouvelles matières.</div>
                  </div>
                  <span style={{ color: '#ff6584', fontWeight: 700, fontSize: '.85rem' }}>Examiner →</span>
                </div>
              )}
            </div>
          )}
          <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.8fr', gap: 24 }}>
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <div style={{ fontWeight: 700, marginBottom: 16 }}>📊 Activité récente</div>
              <p style={{ color: 'var(--text2)' }}>{stats.reservations_mois || 0} nouvelles réservations ce mois-ci.</p>
            </div>
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <div style={{ fontWeight: 700, marginBottom: 16 }}>🏆 Top Professeurs</div>
              {allProfs.filter(p => p.statut_validation === 'validé').slice(0, 4).map(p => (
                <div key={p.id} onClick={() => { setTab('profs'); setSelectedProf(p); }} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0', borderBottom: '1px solid var(--border)', cursor: 'pointer' }}>
                  <span style={{ fontSize: '.88rem' }}>{p.user_prenom} {p.user_nom}</span>
                  <span style={{ color: '#f59e0b', fontWeight: 700 }}>★ {parseFloat(p.note_moyenne || 0).toFixed(1)}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* PROFESSEURS */}
      {tab === 'profs' && (
        <div>
          {pendingProfs.length > 0 && (
            <div style={{ marginBottom: 24, background: 'var(--card)', border: '1px solid rgba(245,158,11,0.3)', borderRadius: 20, padding: 20 }}>
              <div style={{ color: '#f59e0b', fontWeight: 700, fontSize: '.88rem', marginBottom: 14 }}>⚠️ {pendingProfs.length} PROFESSEUR{pendingProfs.length > 1 ? 'S' : ''} EN ATTENTE</div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: 10 }}>
                {pendingProfs.map(p => {
                  const nom  = `${p.user_prenom || ''} ${p.user_nom || ''}`.trim();
                  const mats = p.tarifs_matieres ? [...new Set(p.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 2) : [];
                  return (
                    <div key={p.id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 14px', background: 'rgba(245,158,11,0.05)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 12 }}>
                      <div style={{ width: 42, height: 42, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0, overflow: 'hidden' }}>
                        {p.photo_url ? <img src={'http://localhost:8001' + p.photo_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: 700, fontSize: '.88rem', marginBottom: 2 }}>{nom}</div>
                        <div style={{ fontSize: '.73rem', color: 'var(--text2)' }}>{p.ville && `📍 ${p.ville} · `}{mats.join(', ') || 'Matières non renseignées'}</div>
                      </div>
                      <div style={{ display: 'flex', gap: 6 }}>
                        <button onClick={() => setSelectedProf(p)} style={{ padding: '5px 9px', background: 'rgba(108,99,255,0.15)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.3)', borderRadius: 7, cursor: 'pointer', fontSize: '.72rem', fontWeight: 600 }}>👁</button>
                        <button onClick={() => handleValider(p.id)} style={{ padding: '5px 9px', background: 'rgba(67,233,123,0.15)', color: '#43e97b', border: '1px solid rgba(67,233,123,0.3)', borderRadius: 7, cursor: 'pointer', fontSize: '.72rem', fontWeight: 700 }}>✅</button>
                        <button onClick={() => handleRefuser(p.id)} style={{ padding: '5px 9px', background: 'rgba(255,101,132,0.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,0.25)', borderRadius: 7, cursor: 'pointer', fontSize: '.72rem', fontWeight: 700 }}>❌</button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
          <div style={{ display: 'flex', gap: 12, marginBottom: 20, alignItems: 'center', flexWrap: 'wrap' }}>
            <div style={{ position: 'relative', flex: 1, minWidth: 200 }}>
              <span style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)' }}>🔍</span>
              <input style={{ ...inp, width: '100%', paddingLeft: 34, boxSizing: 'border-box' }} placeholder="Rechercher par nom ou ville..." value={searchProf} onChange={e => setSearchProf(e.target.value)} />
            </div>
            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              {[
                { key: 'tous', label: 'Tous', color: '#6c63ff' },
                { key: 'validé', label: 'Validés', color: '#43e97b' },
                { key: 'en_attente', label: 'En attente', color: '#f59e0b' },
                { key: 'refusé', label: 'Refusés', color: '#ff6584' },
              ].map(s => (
                <button key={s.key} onClick={() => setFilterStatut(s.key)} style={{ padding: '8px 13px', borderRadius: 20, cursor: 'pointer', fontWeight: 600, fontSize: '.78rem', border: filterStatut === s.key ? `1px solid ${s.color}` : '1px solid var(--border)', background: filterStatut === s.key ? `${s.color}20` : 'var(--surface2)', color: filterStatut === s.key ? s.color : 'var(--text2)', display: 'flex', alignItems: 'center', gap: 5 }}>
                  {s.label}
                  <span style={{ background: filterStatut === s.key ? s.color : 'var(--border)', color: filterStatut === s.key ? '#000' : 'var(--text2)', fontSize: '.62rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20 }}>{counts[s.key]}</span>
                </button>
              ))}
            </div>
            <div style={{ fontSize: '.82rem', color: 'var(--text2)' }}>{profsFiltered.length} résultat{profsFiltered.length !== 1 ? 's' : ''}</div>
          </div>
          {profsFiltered.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 20px', background: 'var(--card)', borderRadius: 20, border: '1px solid var(--border)', color: 'var(--text2)' }}>
              <div style={{ fontSize: '2.5rem', marginBottom: 12 }}>🔍</div>
              <div style={{ fontWeight: 600 }}>Aucun professeur trouvé</div>
            </div>
          ) : (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 20 }}>
              {profsFiltered.map(p => <ProfCard key={p.id} prof={p} onView={setSelectedProf} onValider={handleValider} onRefuser={handleRefuser} />)}
            </div>
          )}
        </div>
      )}

      {/* DEMANDES MATIÈRES */}
      {tab === 'demandes' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16 }}>
            {[
              { label: 'En attente', count: demandes.filter(d => d.statut === 'en_attente').length, color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
              { label: 'Approuvées', count: demandes.filter(d => d.statut === 'approuvé').length,   color: '#43e97b', bg: 'rgba(67,233,123,0.1)'  },
              { label: 'Refusées',   count: demandes.filter(d => d.statut === 'refusé').length,     color: '#ff6584', bg: 'rgba(255,101,132,0.1)' },
            ].map(s => (
              <div key={s.label} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 14 }}>
                <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center' }}><span style={{ fontFamily: 'Syne', fontSize: '1.3rem', fontWeight: 800, color: s.color }}>{s.count}</span></div>
                <div style={{ fontSize: '.85rem', color: 'var(--text2)', fontWeight: 600 }}>{s.label}</div>
              </div>
            ))}
          </div>
          {demandes.filter(d => d.statut === 'en_attente').length > 0 ? (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginTop: 0, marginBottom: 20, color: '#f59e0b' }}>⏳ Demandes en attente</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                {demandes.filter(d => d.statut === 'en_attente').map(d => (
                  <div key={d.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '16px 20px', background: 'rgba(245,158,11,0.05)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 14 }}>
                    <div>
                      <div style={{ fontWeight: 700, fontSize: '1rem', marginBottom: 4 }}>💡 {d.nom_matiere}</div>
                      <div style={{ display: 'flex', gap: 12, fontSize: '.8rem', color: 'var(--text2)' }}>
                        <span>🎓 {d.nom_niveau}</span><span>👨‍🏫 {d.prof_nom}</span><span>🕐 {new Date(d.created_at).toLocaleDateString('fr-FR')}</span>
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: 10 }}>
                      <button onClick={() => handleApprouverDemande(d.id)} style={{ padding: '9px 18px', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', color: '#000', border: 'none', borderRadius: 10, fontWeight: 700, cursor: 'pointer', fontSize: '.85rem' }}>✅ Approuver</button>
                      <button onClick={() => handleRefuserDemande(d.id)} style={{ padding: '9px 18px', background: 'transparent', color: '#ff6584', border: '1px solid #ff6584', borderRadius: 10, fontWeight: 600, cursor: 'pointer', fontSize: '.85rem' }}>❌ Refuser</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 40, textAlign: 'center', color: 'var(--text2)' }}>
              <div style={{ fontSize: '2rem', marginBottom: 10 }}>✅</div>
              <div style={{ fontWeight: 600 }}>Aucune demande en attente</div>
            </div>
          )}
          {demandes.filter(d => d.statut !== 'en_attente').length > 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginTop: 0, marginBottom: 20 }}>📋 Historique</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead><tr style={{ textAlign: 'left', color: 'var(--text2)', fontSize: '.78rem', borderBottom: '1px solid var(--border)' }}>{['MATIÈRE','NIVEAU','PROFESSEUR','DATE','STATUT'].map(h => <th key={h} style={{ padding: '10px 12px' }}>{h}</th>)}</tr></thead>
                <tbody>
                  {demandes.filter(d => d.statut !== 'en_attente').map(d => (
                    <tr key={d.id} style={{ borderBottom: '1px solid var(--border)' }}>
                      <td style={{ padding: '12px', fontWeight: 600 }}>{d.nom_matiere}</td>
                      <td style={{ padding: '12px', fontSize: '.85rem', color: 'var(--text2)' }}>{d.nom_niveau}</td>
                      <td style={{ padding: '12px', fontSize: '.85rem' }}>{d.prof_nom}</td>
                      <td style={{ padding: '12px', fontSize: '.82rem', color: 'var(--text2)' }}>{new Date(d.created_at).toLocaleDateString('fr-FR')}</td>
                      <td style={{ padding: '12px' }}><StatutBadge statut={d.statut} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* RÉFÉRENTIEL */}
      {tab === 'referentiel' && (
        <ReferentielTab
          structure={structure}
          villes={villes}
          onReload={loadAllData}
        />
      )}

      <ProfDrawer prof={selectedProf} onClose={() => setSelectedProf(null)} onValider={handleValider} onRefuser={handleRefuser} />
    </div>
  );
}
